import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';import {join} from 'node:path';
const {createTask,updateTask,listForDay,MemoryStore,toTaskJson,fromTaskJson,plannerView}=await import(pathToFileURL(join(process.argv[2],'src/index.ts')).href);
const results=[];const check=(name,fn)=>{try{fn();results.push({name,pass:true});}catch(e){results.push({name,pass:false,error:e.message.slice(0,500)});}};
const make=(id,extra={})=>createTask({id,workspaceId:'w',ownerId:'u',title:'Task '+id,plannedFor:'2026-01-01',position:0,...extra});
const invalid=fn=>assert.throws(fn,e=>e?.code==='INVALID_PRIORITY');
check('default-normal',()=>assert.equal(make('x').priority,'normal'));
check('create-three-levels',()=>{for(const priority of ['low','normal','high'])assert.equal(make('x',{priority}).priority,priority);});
check('create-invalid',()=>{for(const priority of [null,'',1,'urgent',{},false])invalid(()=>make('x',{priority}));});
check('create-explicit-undefined',()=>assert.equal(make('x',{priority:undefined}).priority,'normal'));
check('update-priority-immutable',()=>{const a=make('x',{priority:'low'}),b=updateTask(a,{priority:'high'});assert.equal(a.priority,'low');assert.equal(b.priority,'high');assert.notEqual(a,b);});
check('update-invalid-atomic',()=>{for(const priority of [null,'',1,'urgent',{},false]){const a=make('x',{priority:'low'}),before=structuredClone(a);invalid(()=>updateTask(a,{title:'Changed',priority}));assert.deepEqual(a,before);}});
check('update-omitted-preserves',()=>assert.equal(updateTask(make('x',{priority:'high'}),{title:'New'}).priority,'high'));
check('update-undefined-preserves',()=>assert.equal(updateTask(make('x',{priority:'high'}),{priority:undefined}).priority,'high'));
check('json-emits',()=>assert.equal(toTaskJson(make('x',{priority:'high'})).priority,'high'));
check('json-roundtrip',()=>{for(const priority of ['low','normal','high']){const a=make('x',{priority});assert.deepEqual(fromTaskJson(toTaskJson(a)),a);}});
check('legacy-json-default',()=>{const j=toTaskJson(make('x'));delete j.priority;assert.equal(fromTaskJson(j).priority,'normal');});
check('json-invalid',()=>{for(const priority of [null,'',5,'urgent',{}])invalid(()=>fromTaskJson({...toTaskJson(make('x')),priority}));});
check('priority-order',()=>assert.deepEqual(listForDay([make('n',{priority:'normal'}),make('l',{priority:'low'}),make('h',{priority:'high',position:99})],'w','u','2026-01-01').map(t=>t.id),['h','n','l']));
check('secondary-order',()=>assert.deepEqual(listForDay([make('z',{priority:'high',position:1}),make('b',{priority:'high'}),make('a',{priority:'high'})],'w','u','2026-01-01').map(t=>t.id),['a','b','z']));
check('tenant-owner-day-done',()=>assert.deepEqual(listForDay([make('ok'),make('owner',{priority:'high',ownerId:'other'}),make('workspace',{priority:'high',workspaceId:'other'}),make('day',{priority:'high',plannedFor:'2026-01-02'}),updateTask(make('done',{priority:'high'}),{state:'done'})],'w','u','2026-01-01').map(t=>t.id),['ok']));
check('sort-does-not-mutate',()=>{const xs=[Object.freeze(make('l',{priority:'low'})),Object.freeze(make('h',{priority:'high'}))],before=structuredClone(xs);Object.freeze(xs);assert.deepEqual(listForDay(xs,'w','u','2026-01-01').map(t=>t.id),['h','l']);assert.deepEqual(xs,before);});
check('legacy-sort-normal',()=>{const old={...make('a')};delete old.priority;assert.deepEqual(listForDay([make('l',{priority:'low'}),old,make('h',{priority:'high'})],'w','u','2026-01-01').map(t=>t.id),['h','a','l']);});
check('store-retains-priority',()=>{const s=new MemoryStore();s.save(make('x',{priority:'high'}));s.save(make('x',{workspaceId:'other',priority:'low'}));assert.equal(s.get('w','x').priority,'high');const copy=s.get('w','x');copy.priority='low';assert.equal(s.get('w','x').priority,'high');assert.equal(s.get('other','x').priority,'low');});
check('planner-view',()=>assert.deepEqual(plannerView([make('l',{priority:'low'}),make('h',{priority:'high'})],'w','u','2026-01-01').map(t=>[t.id,t.priority]),[['h','high'],['l','low']]));
check('existing-fields-errors',()=>{const a=make('x',{priority:'high',position:2});assert.equal(a.state,'open');assert.equal(a.position,2);assert.equal(a.title,'Task x');assert.throws(()=>make('x',{title:''}),e=>e.code==='INVALID_TASK');});
console.log(JSON.stringify({passed:results.filter(r=>r.pass).length,total:results.length,results}));process.exitCode=results.every(r=>r.pass)?0:1;
